CREATE TABLE "atlas_mapstate" ("id" smallint NOT NULL PRIMARY KEY CHECK ("id" >= 0), "initialized" boolean NOT NULL, "revision_id" bigint NULL, CONSTRAINT "singleton_map_state" CHECK ("id" = 1));
